from typing import List

class Solution:
    def numSpecialEquivGroups(self, words: List[str]) -> int:
        signatures = {
            ("".join(sorted(w[0::2])), "".join(sorted(w[1::2])))
            for w in words
        }
        return len(signatures)

class Solution {
public:
    int numSpecialEquivGroups(vector<string>& words) {
        unordered_set<string> sigs;
        for (string& w : words) {
            string even = "", odd = "";
            for (size_t i = 0; i < w.length(); i++) {
                if (i % 2 == 0) even += w[i];
                else odd += w[i];
            }
            sort(even.begin(), even.end());
            sort(odd.begin(), odd.end());
            sigs.insert(even + "#" + odd);
        }
        return sigs.size();
    }
};

class Solution {
    public int numSpecialEquivGroups(String[] words) {
        Set<String> sigs = new HashSet<>();
        for (String w : words) {
            StringBuilder even = new StringBuilder();
            StringBuilder odd = new StringBuilder();
            for (int i = 0; i < w.length(); i++) {
                if (i % 2 == 0) even.append(w.charAt(i));
                else odd.append(w.charAt(i));
            }
            char[] eArr = even.toString().toCharArray();
            char[] oArr = odd.toString().toCharArray();
            Arrays.sort(eArr);
            Arrays.sort(oArr);
            sigs.add(new String(eArr) + "#" + new String(oArr));
        }
        return sigs.size();
    }
}

var numSpecialEquivGroups = function(words) {
    const sigs = new Set();
    for (const w of words) {
        let even = [], odd = [];
        for (let i = 0; i < w.length; i++) {
            if (i % 2 === 0) even.push(w[i]);
            else odd.push(w[i]);
        }
        even.sort();
        odd.sort();
        sigs.add(`${even.join('')}#${odd.join('')}`);
    }
    return sigs.size;
};
